SELECT * FROM operation_logs_statistics
WHERE is_deleted = 0 AND statistic_date BETWEEN #{startDate} AND #{endDate}
ORDER BY statistic_date DESC, operation_count DESC

SELECT * FROM operation_logs_statistics
WHERE is_deleted = 0 AND module = #{module}
AND statistic_date BETWEEN #{startDate} AND #{endDate}
ORDER BY statistic_date DESC

SELECT * FROM operation_logs_statistics
WHERE is_deleted = 0 AND operation_type = #{operationType}
AND statistic_date BETWEEN #{startDate} AND #{endDate}
ORDER BY statistic_date DESC

SELECT * FROM operation_logs_statistics
WHERE is_deleted = 0 AND statistic_date = #{statisticDate}

    AND module = #{module}


    AND operation_type = #{operationType}

LIMIT 1
